16	    output     logic done,   // calculation is complete (high for one tick)
17	    output     logic valid,  // result is valid
18	    output     logic dbz,    // divide by zero
19	    output     logic ovf,    // overflow
20	    input wire logic signed [WIDTH-1:0] a,   // dividend (numerator)
21	    input wire logic signed [WIDTH-1:0] b,   // divisor (denominator)
22	    output     logic signed [WIDTH-1:0] val  // result value: quotient
23	    );
