25	    localparam WIDTHU = WIDTH - 1;                 // unsigned widths are 1 bit narrower
26	    localparam FBITSW = (FBITS == 0) ? 1 : FBITS;  // avoid negative vector width when FBITS=0
27	    localparam SMALLEST = {1'b1, {WIDTHU{1'b0}}};  // smallest negative number
28	
29	    localparam ITER = WIDTHU + FBITS;  // iteration count: unsigned input width + fractional bits
30	    logic [$clog2(ITER):0] i;          // iteration counter (allow ITER+1 iterations for rounding)
31	
32	    logic a_sig, b_sig, sig_diff;      // signs of inputs and whether different
33	    logic [WIDTHU-1:0] au, bu;         // absolute version of inputs (unsigned)
34	    logic [WIDTHU-1:0] quo, quo_next;  // intermediate quotients (unsigned)
35	    logic [WIDTHU:0] acc, acc_next;    // accumulator (unsigned but 1 bit wider)
36	
37	    // input signs
38	    always_comb begin
39	        a_sig = a[WIDTH-1+:1];
40	        b_sig = b[WIDTH-1+:1];
41	    end
42	
43	    // division algorithm iteration
44	    always_comb begin
45	        if (acc >= {1'b0, bu}) begin
46	            acc_next = acc - bu;
47	            {acc_next, quo_next} = {acc_next[WIDTHU-1:0], quo, 1'b1};
48	        end else begin
49	            {acc_next, quo_next} = {acc, quo} << 1;
50	        end
51	    end
52	
53	    // calculation state machine
54	    enum {IDLE, INIT, CALC, ROUND, SIGN} state;
55	    always_ff @(posedge clk) begin
56	        done <= 0;
57	        case (state)
58	            INIT: begin
59	                state <= CALC;
60	                ovf <= 0;
61	                i <= 0;
62	                {acc, quo} <= {{WIDTHU{1'b0}}, au, 1'b0};  // initialize calculation
63	            end
64	            CALC: begin
65	                if (i == WIDTHU-1 && quo_next[WIDTHU-1:WIDTHU-FBITSW] != 0) begin  // overflow
66	                    state <= IDLE;
67	                    busy <= 0;
68	                    done <= 1;
69	                    ovf <= 1;
70	                end else begin
71	                    if (i == ITER-1) state <= ROUND;  // calculation complete after next iteration
72	                    i <= i + 1;
73	                    acc <= acc_next;
74	                    quo <= quo_next;
75	                end
76	            end
77	            ROUND: begin  // Gaussian rounding
78	                state <= SIGN;
79	                if (quo_next[0] == 1'b1) begin  // next digit is 1, so consider rounding
80	                    // round up if quotient is odd or remainder is non-zero
81	                    if (quo[0] == 1'b1 || acc_next[WIDTHU:1] != 0) quo <= quo + 1;
82	                end
83	            end
